// Titration of a strong acid analyte with a strong base titrant.
// Analyte: fixed Va mL of Ca mol/L acid. Titrant: P.M mol/L base, P.V mL delivered.
const Ca = 0.100;                 // analyte conc (mol/L)
const Va = 25.0;                  // analyte volume (mL)
const M = Math.max(P.M, 0.01);    // titrant molarity (guard >0)
const nA = Ca * Va / 1000;        // moles of analyte H+ (mol)
const Veq = nA / M * 1000;        // equivalence volume (mL)
const V = Math.min(P.V, 50);      // delivered titrant volume (mL)
const nB = M * V / 1000;          // moles base added (mol)
function pHat(vol){
  const nb = M * vol / 1000;
  const diff = nA - nb;
  const Vtot = (Va + vol) / 1000;
  if (Math.abs(diff) < 1e-12) return 7;
  if (diff > 0){ const Hc = diff / Vtot; return -Math.log10(Math.min(Math.max(Hc,1e-14),1)); }
  const OHc = (-diff) / Vtot; const pOH = -Math.log10(Math.min(Math.max(OHc,1e-14),1)); return 14 - pOH;
}
